import{_ as d,o,c as t,a2 as c}from"./chunks/framework.DoCD98hS.js";const b=JSON.parse('{"title":"选择核心库与框架适配","description":"","frontmatter":{},"headers":[],"relativePath":"guide/core.md","filePath":"guide/core.md","lastUpdated":1795182147000}'),l={name:"guide/core.md"};function a(r,e,i,s,p,n){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="选择核心库与框架适配" tabindex="-1">选择核心库与框架适配 <a class="header-anchor" href="#选择核心库与框架适配" aria-label="Permalink to &quot;选择核心库与框架适配&quot;">​</a></h1><p>应用直接使用 <code>libs-core</code> 加载远程模块。如果还需要把远程组件包装成带加载提示和重试按钮的组件，再添加与你的框架匹配的适配包。</p><h2 id="分层职责" tabindex="-1">分层职责 <a class="header-anchor" href="#分层职责" aria-label="Permalink to &quot;分层职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>放什么</th><th>不放什么</th></tr></thead><tbody><tr><td><code>libs-core</code></td><td>框架无关的加载、地址解析、导出校验、错误规范；可复用的请求协调等</td><td>Vue / React 组件、VNode、hooks 和具体业务清单</td></tr><tr><td><code>libs-core-vue2</code></td><td>Vue 2 生命周期、参数/事件/插槽透传、加载与错误展示</td><td>重复实现底层远程协议</td></tr><tr><td><code>libs-core-vue3</code></td><td>Vue 3 生命周期、参数/事件/插槽透传、加载与错误展示</td><td>重复实现底层远程协议</td></tr><tr><td><code>libs-core-react</code></td><td>React 生命周期、props/children/ref 透传与渲染错误边界</td><td>重复实现底层远程协议</td></tr><tr><td><code>comps-*</code> / 专题 <code>libs-*</code></td><td>公共组件与领域能力本身</td><td>面向所有应用的通用加载器</td></tr><tr><td><code>demo-*</code> / <code>tpl-*</code></td><td>选择模块、版本与加载时机，编排业务</td><td>复制一套本可共用的核心逻辑</td></tr></tbody></table><p>适配层是薄封装，不是三个互不相干的 SDK。能复用的状态逻辑与配置语义保持一致，只有组件模型和生命周期差异留在各框架里。</p><h2 id="当前已有" tabindex="-1">当前已有 <a class="header-anchor" href="#当前已有" aria-label="Permalink to &quot;当前已有&quot;">​</a></h2><p><code>libs-core</code> 是宿主侧工具箱，不维护具体应用的远程依赖清单，也不构建为远程组件。目前提供：</p><ul><li><code>loadHelLib</code>：单模块加载。</li><li><code>preloadHelLibs</code>：统一 <code>{ type, base, deps }</code>，按 libs、comps、其他三批阻塞加载。</li><li><code>resolveHelDep</code> / <code>resolveHelDeps</code>：解析包名、版本、完整 URL 和加载顺序；只解析，不下载。</li><li><code>HEL_BASES</code>：通用 unpkg 站点；GitHub 从依赖的 <code>@scope</code> 推导组织，或由调用方传入 <code>base</code>，公共库不内置组织名。</li><li><code>createHelLoader</code>：创建独立加载器，默认导出的加载方法共享同一个实例。</li><li><code>loadHelLibsSerial</code>：按顺序加载多个模块。</li><li><code>assertHelExports</code>：检查所需导出。</li><li><code>HelLoadError</code>：携带模块、地址和加载阶段等信息的统一错误。</li><li><code>isHelMetaHost</code> / <code>resolveHelHost</code>：元数据地址识别与部署地址解析。</li><li><code>loadHelComponent</code>：加载并检查指定组件导出。</li><li><code>createHelComponentResource</code>：各框架共用的加载、错误、手动重试与卸载状态协调。</li></ul><p>预加载与单包按需加载共用请求缓存和串行队列；失败请求会释放，允许显式重试。同一平台、同一组名绑定不同地址或版本会报配置错误。地址协议见<a href="./loading.html">预加载与懒加载</a>。</p><div class="tip custom-block"><p class="custom-block-title">使用边界</p><p>三个 <code>libs-core-*</code> 框架适配包已经提供加载提示、下载/导出错误提示、渲染错误兜底与手动重试。框架运行时绑定和业务注入仍由宿主负责；超时、网络取消和自动重试未内置。适配包是普通本地依赖，无需再远程预加载。</p></div>',10)])])}const u=d(l,[["render",a]]);export{b as __pageData,u as default};
